using System;
using System.Net;
using System.Net.Sockets;
using System.Text;

class HelloWorldServer
{
    static void Main(string[] args)
    {
        // Crée un nouveau HttpListener qui écoute sur le port 8080
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");

        // Démarre le listener
        listener.Start();

        Console.WriteLine("Server started. Press Enter to stop.");

        // Traitement des requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Vérifie si la requête est pour la page "hello"
            if (request.Url.AbsolutePath.EndsWith("/hello", StringComparison.OrdinalIgnoreCase))
            {
                // Envoie une réponse avec le texte "Hello"
                string response = "<html><body>Hello</body></html>";
                context.Response.ContentType = "text/html";
                context.Response.Write(response);
                context.Response.StatusCode = 200;
                context.Response.Close();
            }
            else
            {
                // Envoie une réponse d'erreur
                context.Response.StatusCode = 404;
                context.Response.Close();
            }
        }
    }
}
```
